std::size_t skip_separator(std::string_view text, std::size_t pos) {
    if (pos == 0 || pos >= text.size() || text[pos] != ' ') {
        return pos;
    }
    const std::size_t next = text.find_first_not_of(' ', pos);
    if (next == std::string_view::npos) {
        fail("trailing space", text);
    }
    return next;
}

